option.value:
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.3.5'
    id 'io.spring.dependency-management' version '1.1.6'
}

group = 'com.storytelling'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-thymeleaf'
    implementation 'org.springframework.boot:spring-boot-starter-validation'

    // langchain4j: LLM integration + structured outputs (used as a toolkit, not agents)
    implementation platform('dev.langchain4j:langchain4j-bom:0.36.2')
    implementation 'dev.langchain4j:langchain4j'
    implementation 'dev.langchain4j:langchain4j-ollama'

    // Required by spring-web's MultipartBodyBuilder (references org.reactivestreams.Publisher).
    implementation 'org.reactivestreams:reactive-streams:1.0.4'

    // Apache HttpComponents: gives RestClient a multipart writer that FastAPI's
    // UploadFile accepts (the default HttpURLConnection-based factory does not).
    implementation 'org.apache.httpcomponents.client5:httpclient5'

    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

tasks.named('test') {
    useJUnitPlatform()
}

package com.storytelling;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.scheduling.annotation.EnableAsync;

import com.storytelling.config.AppProperties;

@EnableAsync
@SpringBootApplication
@EnableConfigurationProperties(AppProperties.class)
public class StoryTellingApplication {

    public static void main(String[] args) {
        SpringApplication.run(StoryTellingApplication.class, args);
    }
}

package com.storytelling.client;

import java.nio.file.Path;

import org.springframework.core.io.FileSystemResource;
import org.springframework.http.HttpEntity;
import org.springframework.http.client.MultipartBodyBuilder;
import org.springframework.stereotype.Component;
import org.springframework.util.MultiValueMap;
import org.springframework.web.client.RestClient;

import com.storytelling.config.AppProperties;
import com.storytelling.model.TranscriptResult;

/**
 * Calls the Python transcription FastAPI service (faster-whisper + pyannote) to
 * transcribe + diarize an audio file.
 */
@Component
public class TranscriptionClient {

    private final RestClient client;
    private final AppProperties props;

    public TranscriptionClient(RestClient transcriptionRestClient, AppProperties props) {
        this.client = transcriptionRestClient;
        this.props = props;
    }

    public TranscriptResult transcribe(Path audioFile) {
        // MultipartBodyBuilder produces proper per-part headers (Content-Disposition
        // with a filename for the file part) that FastAPI's UploadFile requires.
        MultipartBodyBuilder builder = new MultipartBodyBuilder();
        builder.part("file", new FileSystemResource(audioFile))
                .filename(audioFile.getFileName().toString());
        builder.part("model", props.getTranscription().getModel());
        builder.part("glossary", props.getTranscription().getGlossary());
        MultiValueMap<String, HttpEntity<?>> body = builder.build();

        // NOTE: do NOT set Content-Type manually here. Spring's FormHttpMessageConverter
        // detects the MultiValueMap<String, HttpEntity<?>> body and writes it as
        // multipart/form-data *with a generated boundary*. Forcing
        // MediaType.MULTIPART_FORM_DATA emits a Content-Type without a boundary, leaving
        // the server unable to parse any parts (FastAPI then reports `file` as missing).
        return client.post()
                .uri("/transcribe")
                .body(body)
                .retrieve()
                .body(TranscriptResult.class);
    }
}

package com.storytelling.llm;

import com.storytelling.model.SceneList;

import dev.langchain4j.service.SystemMessage;
import dev.langchain4j.service.UserMessage;
import dev.langchain4j.service.V;

/**
 * langchain4j-backed assistant. Two responsibilities:
 *  1) map-reduce summarization of a long transcript into a flowing third-person narration
 *  2) segmentation of that narration into discrete scenes with image prompts (structured output)
 */
public interface NarrationAssistant {

    @SystemMessage("""
            You are a masterful fantasy chronicler. You turn raw, messy tabletop RPG
            (Dungeons & Dragons) session transcripts into vivid third-person prose.
            Write in past tense, third person. Refer to characters by their character names.
            Do NOT mention dice, rules, the players, or out-of-character chatter.
            Only narrate the in-world story.
            """)
    @UserMessage("""
            Here is the story so far (may be empty):
            ---
            {{storySoFar}}
            ---
            Continue the chronicle using ONLY this next portion of the transcript.
            Keep it tight: summarize the key events as narrative prose, 1-3 paragraphs.

            Transcript portion:
            ---
            {{chunk}}
            ---
            """)
    String summarizeChunk(@V("storySoFar") String storySoFar, @V("chunk") String chunk);

    @SystemMessage("""
            You are a story editor. You split a finished narrative into a sequence of
            distinct visual SCENES suitable for illustration. For each scene produce a
            title, a 2-4 sentence third-person narration, the characters present, and a
            detailed Stable Diffusion image prompt describing setting, characters,
            mood and composition. Leave imagePath empty.
            """)
    @UserMessage("""
            Split the following chronicle into 5 to 12 illustratable scenes.

            Chronicle:
            ---
            {{narration}}
            ---
            """)
    SceneList segmentScenes(@V("narration") String narration);
}

package com.storytelling.model;

import java.util.List;

/** The LLM's scene-segmentation output: an ordered list of scenes. */
public record SceneList(List<SceneSpec> scenes) {
}

package com.storytelling.model;

import java.util.List;

import dev.langchain4j.model.output.structured.Description;

/**
 * A single scene extracted from the narration, with a ready-to-use image prompt.
 * Annotated so langchain4j can drive structured (JSON) output from the LLM.
 */
public record SceneSpec(
        @Description("short evocative scene title") String title,
        @Description("third-person narration of this scene, 2-4 sentences") String narration,
        @Description("a vivid Stable Diffusion image prompt describing the scene visually") String imagePrompt,
        @Description("names of characters present in the scene") List<String> characters,
        @Description("relative path to the generated image file, leave empty") String imagePath) {
}

package com.storytelling.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * The full, persisted state of a session. Serialized to {dataDir}/{id}/session.json
 * so the pipeline is resumable across restarts. Mutable by design.
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public class Session {

    private String id;
    private String originalAudioFilename;
    private SessionStatus status = SessionStatus.CREATED;
    private Instant createdAt = Instant.now();
    private Instant updatedAt = Instant.now();
    private String errorMessage;

    private TranscriptResult transcript;
    private List<SpeakerLabel> speakerLabels = new ArrayList<>();
    private String narration;
    private List<SceneSpec> scenes = new ArrayList<>();

    public Session() {
    }

    public Session(String id, String originalAudioFilename) {
        this.id = id;
        this.originalAudioFilename = originalAudioFilename;
    }

    public void touch() {
        this.updatedAt = Instant.now();
    }

    // getters / setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    public String getOriginalAudioFilename() { return originalAudioFilename; }
    public void setOriginalAudioFilename(String f) { this.originalAudioFilename = f; }
    public SessionStatus getStatus() { return status; }
    public void setStatus(SessionStatus status) { this.status = status; touch(); }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
    public String getErrorMessage() { return errorMessage; }
    public void setErrorMessage(String errorMessage) { this.errorMessage = errorMessage; }
    public TranscriptResult getTranscript() { return transcript; }
    public void setTranscript(TranscriptResult transcript) { this.transcript = transcript; }
    public List<SpeakerLabel> getSpeakerLabels() { return speakerLabels; }
    public void setSpeakerLabels(List<SpeakerLabel> speakerLabels) { this.speakerLabels = speakerLabels; }
    public String getNarration() { return narration; }
    public void setNarration(String narration) { this.narration = narration; }
    public List<SceneSpec> getScenes() { return scenes; }
    public void setScenes(List<SceneSpec> scenes) { this.scenes = scenes; }
}

package com.storytelling.model;

/**
 * User-provided mapping from a raw diarization label to a player and/or character name.
 * e.g. rawLabel="SPEAKER_00", player="Alice", character="Lyra the Rogue".
 */
public record SpeakerLabel(String rawLabel, String player, String character) {
}

package com.storytelling.model;

/**
 * One diarized utterance from WhisperX: a time-bounded chunk of text spoken by a speaker.
 * `speaker` is a raw diarization label such as "SPEAKER_00" until the user maps it.
 */
public record SpeakerSegment(double start, double end, String speaker, String text) {
}

package com.storytelling.model;

import java.util.List;

/** Raw result returned by the transcription service. */
public record TranscriptResult(String language, List<SpeakerSegment> segments) {
}

package com.storytelling.pipeline;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import com.storytelling.config.AppProperties;
import com.storytelling.model.SpeakerLabel;
import com.storytelling.model.SpeakerSegment;
import com.storytelling.model.TranscriptResult;

/**
 * Pure helpers for turning a diarized transcript into LLM-ready text:
 * applies speaker labels and chunks the (very long) transcript for map-reduce.
 */
public final class TranscriptFormatter {

    private TranscriptFormatter() {
    }

    /** Renders the transcript with human-readable speaker/character names applied. */
    public static String render(TranscriptResult transcript, List<SpeakerLabel> labels) {
        Map<String, String> names = labels.stream()
                .collect(Collectors.toMap(SpeakerLabel::rawLabel, TranscriptFormatter::displayName, (a, b) -> a));

        StringBuilder sb = new StringBuilder();
        for (SpeakerSegment seg : transcript.segments()) {
            String name = names.getOrDefault(seg.speaker(), seg.speaker());
            sb.append(name).append(": ").append(seg.text().strip()).append('\n');
        }
        return sb.toString();
    }

    private static String displayName(SpeakerLabel l) {
        if (l.character() != null && !l.character().isBlank()) return l.character();
        if (l.player() != null && !l.player().isBlank()) return l.player();
        return l.rawLabel();
    }

    /** Splits text into overlapping chunks, breaking on line boundaries where possible. */
    public static List<String> chunk(String text, AppProperties.Narration cfg) {
        int size = cfg.getChunkSizeChars();
        int overlap = cfg.getChunkOverlapChars();
        java.util.ArrayList<String> chunks = new java.util.ArrayList<>();
        int pos = 0;
        int len = text.length();
        while (pos < len) {
            int end = Math.min(pos + size, len);
            if (end < len) {
                int nl = text.lastIndexOf('\n', end);
                if (nl > pos) end = nl;
            }
            chunks.add(text.substring(pos, end));
            if (end >= len) break;
            pos = Math.max(end - overlap, pos + 1);
        }
        return chunks;
    }
}

package com.storytelling.web;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

import org.springframework.core.io.FileSystemResource;
import org.springframework.core.io.Resource;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

import com.storytelling.model.SpeakerLabel;
import com.storytelling.model.SpeakerSegment;
import com.storytelling.model.Session;
import com.storytelling.model.SessionStatus;
import com.storytelling.pipeline.PipelineOrchestrator;
import com.storytelling.store.SessionStore;

@Controller
public class StoryController {

    private final SessionStore store;
    private final PipelineOrchestrator pipeline;

    public StoryController(SessionStore store, PipelineOrchestrator pipeline) {
        this.store = store;
        this.pipeline = pipeline;
    }

    @GetMapping("/")
    public String index(Model model) {
        model.addAttribute("sessions", store.listAll());
        return "index";
    }

    @PostMapping("/sessions")
    public String upload(@RequestParam("audio") MultipartFile audio, RedirectAttributes ra) {
        if (audio.isEmpty()) {
            ra.addFlashAttribute("error", "Please choose an audio file.");
            return "redirect:/";
        }
        String id = UUID.randomUUID().toString().substring(0, 8);
        Session session = new Session(id, audio.getOriginalFilename());
        store.save(session);
        try {
            store.saveAudio(id, audio.getOriginalFilename(), audio.getInputStream());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        pipeline.runTranscription(id); // async
        return "redirect:/sessions/" + id;
    }

    @GetMapping("/sessions/{id}")
    public String view(@PathVariable String id, Model model) {
        Session session = store.load(id).orElseThrow();
        model.addAttribute("story", session);
        model.addAttribute("speakers", distinctSpeakers(session));
        model.addAttribute("autoRefresh", isInProgress(session.getStatus()));
        return "session";
    }

    private static boolean isInProgress(SessionStatus status) {
        return status != SessionStatus.COMPLETED
                && status != SessionStatus.AWAITING_LABELS
                && status != SessionStatus.FAILED;
    }

    @PostMapping("/sessions/{id}/labels")
    public String submitLabels(@PathVariable String id,
                               @RequestParam java.util.Map<String, String> params) {
        Session session = store.load(id).orElseThrow();
        List<SpeakerLabel> labels = new ArrayList<>();
        for (String raw : distinctSpeakers(session)) {
            String player = params.get("player_" + raw);
            String character = params.get("character_" + raw);
            labels.add(new SpeakerLabel(raw, player, character));
        }
        session.setSpeakerLabels(labels);
        store.save(session);
        pipeline.runNarrationAndImages(id); // async
        return "redirect:/sessions/" + id;
    }

    @GetMapping("/sessions/{id}/images/{file}")
    public ResponseEntity<Resource> image(@PathVariable String id, @PathVariable String file) {
        Path path = store.imagesDir(id).resolve(file).normalize();
        if (!path.startsWith(store.imagesDir(id)) || !Files.exists(path)) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok()
                .contentType(MediaType.IMAGE_PNG)
                .body(new FileSystemResource(path));
    }

    private Set<String> distinctSpeakers(Session session) {
        Set<String> speakers = new LinkedHashSet<>();
        if (session.getTranscript() != null) {
            for (SpeakerSegment s : session.getTranscript().segments()) {
                speakers.add(s.speaker());
            }
        }
        return speakers;
    }
}

