body { font-family: system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text);
       max-width: 980px; margin: 0 auto; padding: 24px; line-height: 1.5; }
header h1 { color: var(--accent); }
a { color: var(--accent); }
.muted { color: var(--muted); }
