package com.storytelling.pipeline;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.storytelling.client.ImageClient;
import com.storytelling.client.TranscriptionClient;
import com.storytelling.config.AppProperties;
import com.storytelling.llm.NarrationAssistant;
import com.storytelling.model.SceneList;
import com.storytelling.model.SceneSpec;
import com.storytelling.model.Session;
import com.storytelling.model.SessionStatus;
import com.storytelling.model.SpeakerLabel;
import com.storytelling.model.SpeakerSegment;
import com.storytelling.model.TranscriptResult;
import com.storytelling.store.SessionStore;

/**
 * Exercises the full orchestration logic with the external ML services mocked,
 * but real file-based persistence. Calling the orchestrator methods directly
 * bypasses the @Async proxy, so they run synchronously here.
 */
class PipelineOrchestratorTest {

    @TempDir
    Path tempDir;

    private SessionStore store;
    private TranscriptionClient transcriptionClient;
    private ImageClient imageClient;
    private NarrationAssistant narrationAssistant;
    private PipelineOrchestrator orchestrator;

    @BeforeEach
    void setUp() {
        AppProperties props = new AppProperties();
        props.setDataDir(tempDir.toString());
        ObjectMapper mapper = new ObjectMapper().registerModule(new JavaTimeModule());
        store = new SessionStore(props, mapper);

        transcriptionClient = mock(TranscriptionClient.class);
        imageClient = mock(ImageClient.class);
        narrationAssistant = mock(NarrationAssistant.class);
        orchestrator = new PipelineOrchestrator(store, transcriptionClient, imageClient, narrationAssistant, props);
    }

    @Test
    void runTranscription_storesTranscriptAndPausesForLabels() {
        Session session = new Session("s1", "rec.wav");
        store.save(session);
        store.saveAudio("s1", "rec.wav", new ByteArrayInputStream("audio".getBytes(StandardCharsets.UTF_8)));

        when(transcriptionClient.transcribe(any())).thenReturn(sampleTranscript());

        orchestrator.runTranscription("s1");

        Session result = store.load("s1").orElseThrow();
        assertThat(result.getStatus()).isEqualTo(SessionStatus.AWAITING_LABELS);
        assertThat(result.getTranscript().segments()).hasSize(2);
    }

    @Test
    void runNarrationAndImages_producesNarrationScenesAndImages() throws Exception {
        Session session = new Session("s2", "rec.wav");
        session.setTranscript(sampleTranscript());
        session.setSpeakerLabels(List.of(
                new SpeakerLabel("SPEAKER_00", "Alice", "Lyra"),
                new SpeakerLabel("SPEAKER_01", "Bob", "Thrain")));
        session.setStatus(SessionStatus.AWAITING_LABELS);
        store.save(session);

        when(narrationAssistant.summarizeChunk(anyString(), anyString())).thenReturn("A heroic beat.");
        when(narrationAssistant.segmentScenes(anyString())).thenReturn(new SceneList(List.of(
                new SceneSpec("The Gate", "They reached the gate.", "a stone gate at dusk", List.of("Lyra"), ""),
                new SceneSpec("The Battle", "A fight broke out.", "a fierce sword fight", List.of("Thrain"), ""))));
        when(imageClient.generate(anyString())).thenReturn(new byte[]{(byte) 0x89, 'P', 'N', 'G'});

        orchestrator.runNarrationAndImages("s2");

        Session result = store.load("s2").orElseThrow();
        assertThat(result.getStatus()).isEqualTo(SessionStatus.COMPLETED);
        assertThat(result.getNarration()).contains("A heroic beat.");
        assertThat(result.getScenes()).hasSize(2);
        assertThat(result.getScenes()).allSatisfy(s ->
                assertThat(s.imagePath()).startsWith("images/scene_"));

        Path img1 = store.imagesDir("s2").resolve("scene_01.png");
        Path img2 = store.imagesDir("s2").resolve("scene_02.png");
        assertThat(Files.exists(img1)).isTrue();
        assertThat(Files.exists(img2)).isTrue();
    }

    @Test
    void runTranscription_marksFailedWhenServiceThrows() {
        Session session = new Session("s3", "rec.wav");
        store.save(session);
        store.saveAudio("s3", "rec.wav", new ByteArrayInputStream("audio".getBytes(StandardCharsets.UTF_8)));

        when(transcriptionClient.transcribe(any())).thenThrow(new RuntimeException("service down"));

        orchestrator.runTranscription("s3");

        Session result = store.load("s3").orElseThrow();
        assertThat(result.getStatus()).isEqualTo(SessionStatus.FAILED);
        assertThat(result.getErrorMessage()).contains("service down");
    }

    private static TranscriptResult sampleTranscript() {
        return new TranscriptResult("en", List.of(
                new SpeakerSegment(0, 2, "SPEAKER_00", "We approach the dungeon."),
                new SpeakerSegment(2, 4, "SPEAKER_01", "I draw my axe.")));
    }
}

package com.storytelling.pipeline;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.junit.jupiter.api.Test;

import com.storytelling.config.AppProperties;
import com.storytelling.model.SpeakerLabel;
import com.storytelling.model.SpeakerSegment;
import com.storytelling.model.TranscriptResult;

class TranscriptFormatterTest {

    @Test
    void render_appliesCharacterThenPlayerThenRawLabel() {
        TranscriptResult transcript = new TranscriptResult("en", List.of(
                new SpeakerSegment(0, 1, "SPEAKER_00", "  hello  "),
                new SpeakerSegment(1, 2, "SPEAKER_01", "world"),
                new SpeakerSegment(2, 3, "SPEAKER_99", "unmapped")));

        List<SpeakerLabel> labels = List.of(
                new SpeakerLabel("SPEAKER_00", "Alice", "Lyra"),   // character wins
                new SpeakerLabel("SPEAKER_01", "Bob", ""));        // falls back to player

        String rendered = TranscriptFormatter.render(transcript, labels);

        assertThat(rendered).isEqualTo("""
                Lyra: hello
                Bob: world
                SPEAKER_99: unmapped
                """);
    }

    @Test
    void chunk_returnsSingleChunkWhenShorterThanSize() {
        AppProperties.Narration cfg = narrationCfg(1000, 100);
        List<String> chunks = TranscriptFormatter.chunk("a short line\n", cfg);
        assertThat(chunks).hasSize(1);
    }

    @Test
    void chunk_splitsLongTextWithOverlapAndCoversAllContent() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 50; i++) {
            sb.append("line ").append(i).append(" some narration content\n");
        }
        String text = sb.toString();

        AppProperties.Narration cfg = narrationCfg(120, 30);
        List<String> chunks = TranscriptFormatter.chunk(text, cfg);

        assertThat(chunks).hasSizeGreaterThan(1);
        assertThat(chunks).allSatisfy(c -> assertThat(c).isNotEmpty());
        // every original line must appear somewhere in the chunks
        for (int i = 0; i < 50; i++) {
            String needle = "line " + i + " ";
            assertThat(chunks).anySatisfy(c -> assertThat(c).contains(needle));
        }
    }

    private static AppProperties.Narration narrationCfg(int size, int overlap) {
        AppProperties.Narration cfg = new AppProperties.Narration();
        cfg.setChunkSizeChars(size);
        cfg.setChunkOverlapChars(overlap);
        return cfg;
    }
}

package com.storytelling.store;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.storytelling.config.AppProperties;
import com.storytelling.model.Session;
import com.storytelling.model.SessionStatus;

class SessionStoreTest {

    @TempDir
    Path tempDir;

    private SessionStore store;

    @BeforeEach
    void setUp() {
        AppProperties props = new AppProperties();
        props.setDataDir(tempDir.toString());
        ObjectMapper mapper = new ObjectMapper().registerModule(new JavaTimeModule());
        store = new SessionStore(props, mapper);
    }

    @Test
    void saveAndLoad_roundTripsState() {
        Session session = new Session("abc123", "session1.wav");
        session.setStatus(SessionStatus.AWAITING_LABELS);
        session.setNarration("Once upon a time...");
        store.save(session);

        Optional<Session> loaded = store.load("abc123");

        assertThat(loaded).isPresent();
        assertThat(loaded.get().getId()).isEqualTo("abc123");
        assertThat(loaded.get().getOriginalAudioFilename()).isEqualTo("session1.wav");
        assertThat(loaded.get().getStatus()).isEqualTo(SessionStatus.AWAITING_LABELS);
        assertThat(loaded.get().getNarration()).isEqualTo("Once upon a time...");
    }

    @Test
    void load_returnsEmptyForUnknownSession() {
        assertThat(store.load("does-not-exist")).isEmpty();
    }

    @Test
    void saveAudio_thenFindAudio() {
        byte[] data = "fake audio".getBytes(StandardCharsets.UTF_8);
        store.save(new Session("s1", "rec.mp3"));
        store.saveAudio("s1", "rec.mp3", new ByteArrayInputStream(data));

        Optional<Path> audio = store.findAudio("s1");

        assertThat(audio).isPresent();
        assertThat(audio.get().getFileName().toString()).isEqualTo("audio.mp3");
    }

    @Test
    void listAll_returnsSavedSessions() {
        store.save(new Session("s1", "a.wav"));
        store.save(new Session("s2", "b.wav"));

        List<Session> all = store.listAll();

        assertThat(all).extracting(Session::getId).containsExactlyInAnyOrder("s1", "s2");
    }
}

package com.storytelling.web;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.redirectedUrlPattern;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Executor;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.Bean;
import org.springframework.core.io.ClassPathResource;
import org.springframework.core.task.SyncTaskExecutor;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.storytelling.client.ImageClient;
import com.storytelling.client.TranscriptionClient;
import com.storytelling.llm.NarrationAssistant;
import com.storytelling.model.SceneList;
import com.storytelling.model.SceneSpec;
import com.storytelling.model.Session;
import com.storytelling.model.SessionStatus;
import com.storytelling.model.SpeakerSegment;
import com.storytelling.model.TranscriptResult;
import com.storytelling.store.SessionStore;

/**
 * End-to-end test of the web flow using a real sample audio clip (src/test/resources/sample.m4a).
 * The ML services (WhisperX, Ollama, SDXL) are mocked so the test is hermetic and fast,
 * but the upload, persistence, speaker-labeling, async pipeline and image-serving are all real.
 */
@SpringBootTest(properties = "spring.main.allow-bean-definition-overriding=true")
@AutoConfigureMockMvc
class StoryPipelineIntegrationTest {

    @TempDir
    static Path dataDir;

    @DynamicPropertySource
    static void props(DynamicPropertyRegistry registry) {
        registry.add("storytelling.data-dir", () -> dataDir.toString());
    }

    @Autowired
    MockMvc mockMvc;

    @Autowired
    SessionStore store;

    @MockBean
    TranscriptionClient transcriptionClient;

    @MockBean
    NarrationAssistant narrationAssistant;

    @MockBean
    ImageClient imageClient;

    /** Make @Async pipeline stages run synchronously so the test is deterministic. */
    @TestConfiguration
    static class SyncConfig {
        @Bean(name = "pipelineExecutor")
        Executor pipelineExecutor() {
            return new SyncTaskExecutor();
        }
    }

    @Test
    void fullPipeline_fromUploadToIllustratedChronicle() throws Exception {
        // --- mock the ML services ---
        when(transcriptionClient.transcribe(any())).thenReturn(new TranscriptResult("en", List.of(
                new SpeakerSegment(0, 3, "SPEAKER_00", "We enter the ruined keep."),
                new SpeakerSegment(3, 6, "SPEAKER_01", "I light a torch and look around."))));
        when(narrationAssistant.summarizeChunk(anyString(), anyString()))
                .thenReturn("The party stepped into the ruined keep, torchlight flickering.");
        when(narrationAssistant.segmentScenes(anyString())).thenReturn(new SceneList(List.of(
                new SceneSpec("Into the Keep", "They entered the ruined keep.",
                        "a ruined stone keep lit by torchlight", List.of("Lyra"), ""),
                new SceneSpec("Torchlight", "A torch revealed ancient halls.",
                        "ancient halls revealed by a single torch", List.of("Thrain"), ""))));
        when(imageClient.generate(anyString())).thenReturn(pngBytes());

        // --- 1. upload the sample audio clip ---
        byte[] audio = new ClassPathResource("sample.m4a").getInputStream().readAllBytes();
        MockMultipartFile file = new MockMultipartFile("audio", "sample.m4a", "audio/mp4", audio);

        MvcResult uploadResult = mockMvc.perform(multipart("/sessions").file(file))
                .andExpect(status().is3xxRedirection())
                .andExpect(redirectedUrlPattern("/sessions/*"))
                .andReturn();

        String location = uploadResult.getResponse().getRedirectedUrl();
        String sessionId = location.substring(location.lastIndexOf('/') + 1);

        // --- 2. transcription ran synchronously; we should now await speaker labels ---
        Session afterTranscription = store.load(sessionId).orElseThrow();
        assertThat(afterTranscription.getStatus()).isEqualTo(SessionStatus.AWAITING_LABELS);

        mockMvc.perform(get("/sessions/{id}", sessionId))
                .andExpect(status().isOk())
                .andExpect(content().string(org.hamcrest.Matchers.containsString("Who's who")));

        // --- 3. submit speaker labels -> triggers narration + image generation ---
        mockMvc.perform(post("/sessions/{id}/labels", sessionId)
                        .param("player_SPEAKER_00", "Alice")
                        .param("character_SPEAKER_00", "Lyra")
                        .param("player_SPEAKER_01", "Bob")
                        .param("character_SPEAKER_01", "Thrain"))
                .andExpect(status().is3xxRedirection());

        // --- 4. pipeline completed with narration, scenes and image files ---
        Session done = store.load(sessionId).orElseThrow();
        assertThat(done.getStatus()).isEqualTo(SessionStatus.COMPLETED);
        assertThat(done.getNarration()).isNotBlank();
        assertThat(done.getScenes()).hasSize(2);
        assertThat(done.getScenes()).allSatisfy(s -> assertThat(s.imagePath()).startsWith("images/scene_"));

        Path sceneImage = store.imagesDir(sessionId).resolve("scene_01.png");
        assertThat(Files.exists(sceneImage)).isTrue();

        // --- 5. the generated image is servable over HTTP ---
        mockMvc.perform(get("/sessions/{id}/images/{file}", sessionId, "scene_01.png"))
                .andExpect(status().isOk())
                .andExpect(content().contentType(org.springframework.http.MediaType.IMAGE_PNG));
    }

    private static byte[] pngBytes() {
        // minimal PNG signature + a byte; enough to write and serve as image/png in this test
        return new byte[]{(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A, 0x00};
    }
}

#!/usr/bin/env bash # Shared helpers for the Python service launchers. # # The ML stack (PyTorch, whisperx, tokenizers, av, ctranslate2) ships prebuilt # wheels only for CPython 3.10–3.12. On 3.13/3.14 pip tries to compile from source # and fails. So we deliberately pick a compatible interpreter instead of whatever # `python3` happens to be.
# Print the path to a compatible python, or nothing if none is found. pick_python() { if [ -n "${PYTHON:-}" ] && command -v "$PYTHON" >/dev/null 2>&1; then command -v "$PYTHON"; return fi for c in python3.12 python3.11 python3.10; do if command -v "$c" >/dev/null 2>&1; then command -v "$c"; return; fi done echo "" }
# Print a compatible python path or exit with a helpful message. require_python() { local py; py="$(pick_python)" if [ -z "$py" ]; then echo "ERROR: need Python 3.10–3.12, but none was found." >&2 echo " Default python3 is $(python3 --version 2>&1 | awk '{print $2}'), which has no" >&2 echo " prebuilt wheels for PyTorch/whisperx/tokenizers." >&2 echo " Fix: brew install python@3.12 (or set PYTHON=/path/to/python3.12)" >&2 exit 1 fi echo "$py" }
# Load KEY=VALUE pairs from a git-ignored .env at the repo root, if present. # <repo-root> is the directory that contains the .env file. load_env() { local root="$1" if [ -f "$root/.env" ]; then set -a # shellcheck disable=SC1091 . "$root/.env" set +a fi }
# ensure_venv <venv-dir> <requirements-file> # (Re)builds the venv if it isn't fully installed. Uses a '.installed' sentinel so # a previously *failed/partial* install is retried instead of silently skipped. ensure_venv() { local venv="$1" reqs="$2" py if [ -f "$venv/.installed" ]; then return 0 fi py="$(require_python)" echo "[setup] building venv '$venv' with $("$py" --version 2>&1) (first run can download several GB)..." rm -rf "$venv" "$py" -m venv "$venv" "$venv/bin/pip" install --upgrade pip "$venv/bin/pip" install -r "$reqs" touch "$venv/.installed" }
